"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 600, H = 400;
const XMIN = -2, XMAX = 2, YMIN = -1.5, YMAX = 2.5;

const OPTIMIZERS: Record<string, { name: string; color: string; glyph: string; desc: string }> = {
    GD: {
        name: "GD",
        color: "#60a5fa",
        glyph: "ΓùÅ",
        desc: "Fixed step",
    },
    Momentum: {
        name: "Momentum",
        color: "#f472b6",
        glyph: "Γû▓",
        desc: "Past velocity",
    },
    Adam: {
        name: "Adam",
        color: "#34d399",
        glyph: "Γùå",
        desc: "Adaptive rates",
    },
};

// ΓöÇΓöÇΓöÇ Math Utils ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function toCanvas(x: number, y: number) {
    return [
        ((x - XMIN) / (XMAX - XMIN)) * W,
        H - ((y - YMIN) / (YMAX - YMIN)) * H,
    ];
}

function loss(x: number, y: number) {
    return (
        0.3 * (1 - x) ** 2 * Math.exp(-(x ** 2) - (y + 1) ** 2) -
        (x / 5 - x ** 3 - y ** 5) * Math.exp(-(x ** 2) - y ** 2) -
        (1 / 3) * Math.exp(-((x + 1) ** 2) - y ** 2) +
        0.1 * x ** 2 +
        0.1 * y ** 2
    );
}

function gradient(x: number, y: number, eps = 1e-4) {
    return [
        (loss(x + eps, y) - loss(x - eps, y)) / (2 * eps),
        (loss(x, y + eps) - loss(x, y - eps)) / (2 * eps),
    ];
}

type OptimizerStates = {
    GD: { x: number; y: number; trail: number[][] };
    Momentum: { x: number; y: number; vx: number; vy: number; trail: number[][] };
    Adam: { x: number; y: number; mx: number; my: number; vx: number; vy: number; t: number; trail: number[][] };
};

function makeOptimizerState(x0: number, y0: number): OptimizerStates {
    return {
        GD: { x: x0, y: y0, trail: [[x0, y0]] },
        Momentum: { x: x0, y: y0, vx: 0, vy: 0, trail: [[x0, y0]] },
        Adam: { x: x0, y: y0, mx: 0, my: 0, vx: 0, vy: 0, t: 0, trail: [[x0, y0]] },
    };
}

function stepAll(states: OptimizerStates, lr: number, noise: number): OptimizerStates {
    const next = {} as OptimizerStates;

    // GD
    {
        const s = states.GD;
        const n = noise > 0 ? (Math.random() - 0.5) * noise : 0;
        const [gx, gy] = gradient(s.x + n, s.y + n);
        const nx = s.x - lr * gx;
        const ny = s.y - lr * gy;
        next.GD = { x: nx, y: ny, trail: [...s.trail.slice(-80), [nx, ny]] };
    }

    // Momentum
    {
        const s = states.Momentum;
        const ╬▓ = 0.85;
        const n = noise > 0 ? (Math.random() - 0.5) * noise : 0;
        const [gx, gy] = gradient(s.x + n, s.y + n);
        const vx = ╬▓ * s.vx - lr * gx;
        const vy = ╬▓ * s.vy - lr * gy;
        const nx = s.x + vx;
        const ny = s.y + vy;
        next.Momentum = { x: nx, y: ny, vx, vy, trail: [...s.trail.slice(-80), [nx, ny]] };
    }

    // Adam
    {
        const s = states.Adam;
        const ╬▓1 = 0.9, ╬▓2 = 0.999, ╬╡ = 1e-8;
        const n = noise > 0 ? (Math.random() - 0.5) * noise : 0;
        const [gx, gy] = gradient(s.x + n, s.y + n);
        const t = s.t + 1;
        const mx = ╬▓1 * s.mx + (1 - ╬▓1) * gx;
        const my = ╬▓1 * s.my + (1 - ╬▓1) * gy;
        const vx = ╬▓2 * s.vx + (1 - ╬▓2) * gx * gx;
        const vy = ╬▓2 * s.vy + (1 - ╬▓2) * gy * gy;
        const mxH = mx / (1 - Math.pow(╬▓1, t));
        const myH = my / (1 - Math.pow(╬▓1, t));
        const vxH = vx / (1 - Math.pow(╬▓2, t));
        const vyH = vy / (1 - Math.pow(╬▓2, t));
        const nx = s.x - lr * mxH / (Math.sqrt(vxH) + ╬╡);
        const ny = s.y - lr * myH / (Math.sqrt(vyH) + ╬╡);
        next.Adam = { x: nx, y: ny, mx, my, vx, vy, t, trail: [...s.trail.slice(-80), [nx, ny]] };
    }

    return next;
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function GradientDescentOptimizer() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const contourRef = useRef<HTMLCanvasElement | null>(null);
    const animRef = useRef<number | null>(null);
    const statesRef = useRef<OptimizerStates | null>(null);

    const START = { x: -1.5, y: 1.8 };
    const [running, setRunning] = useState(false);
