const xMin = Math.min(...SEED.map(d => d.x)) - 1, xMax = Math.max(...SEED.map(d => d.x)) + 1;
const yMin = Math.min(...SEED.map(d => d.y)) - 2, yMax = Math.max(...SEED.map(d => d.y)) + 2;
