function toY(y: number) { return PAD.top + pH - ((y - yMin) / (yMax - yMin)) * pH; }
function knn(pt: { x: number }, obs: { x: number; y: number }[], k = 4) {
    return obs.sort((a, b) => Math.abs(a.x - pt.x) - Math.abs(b.x - pt.x)).slice(0, k).reduce((s, n) => s + n.y, 0) / k;
}
const STRATS = [
    { key: "original", label: "Original", color: "#94a3b8", desc: "22% of Y values are missing (grey = missing)" },
    { key: "drop", label: "Drop Rows", color: "#f87171", desc: "Delete rows with missing Y ΓÇö loses ~22% of data" },
    { key: "mean", label: "Mean Impute", color: "#fbbf24", desc: "Replace with column mean ΓÇö kills variance, creates spike" },
    { key: "knn", label: "KNN Impute", color: "#34d399", desc: "Use k=4 nearest X-neighbours ΓÇö preserves local structure" },
] as const;
