        if (strat === "mean") return SEED.map(d => d.missing ? { ...d, y: +meanY.toFixed(2), imputed: true } : { ...d, imputed: false });
        return SEED.map(d => d.missing ? { ...d, y: +knn(d, observed.map(o => ({ ...o }))).toFixed(2), imputed: true } : { ...d, imputed: false });
